74: std::ostream& write_IFD_entry(
75:   std::ostream& os,
76:   Tag tag,
77:   Type type,
78:   uint32_t count,
79:   const std::byte* values,
80:   uint32_t valueOffset = 0,
81:   bool mustSwap = false)
82: {
83:   const uint32_t valueBytes = count * typeBytes(type);
84: 
85:   // Current position in the stream
86:   const uint32_t startPos = static_cast<uint32_t>(os.tellp());
87: 
88:   if (count < 1) {
89:     throw std::runtime_error("Count must be at least 1");
90:   }
91:   if (values == nullptr) {
92:     throw std::runtime_error("Values pointer cannot be null");
93:   }
94:   if (valueOffset - startPos < 12 && valueOffset != 0) {
95:     throw std::runtime_error("Value offset must be zero or greater or equal to 12");
96:   }
97:   if (valueBytes > 4 && valueOffset == 0) {
98:     throw std::runtime_error("Value offset must be provided if values do not fit in 4 bytes");
99:   }
100:   if (valueBytes <= 4 && valueOffset > 0) {
101:     throw std::runtime_error("Value offset must be zero if values fit in 4 bytes");
102:   }
103:   if (valueOffset % 2 != 0) {
104:     throw std::runtime_error("Value offset must be even");
105:   }
106: 
107:   writeValue(os, tag, mustSwap);
108:   writeValue(os, type, mustSwap);
109:   writeValue(os, count, mustSwap);
110: 
111:   if (valueBytes <= 4) {
112:     // Values fit in 4 bytes, write them directly
113:     std::vector<std::byte> valueBytesVec(4, std::byte{0});
114:     std::copy(values, values + valueBytes, valueBytesVec.data());
115:     if (mustSwap) {
116:       // Note that we swap values as an array, instead of as a single `uint32_t`
117:       // This is because the values may not be a single `uint32_t` but rather
118:       // a sequence of smaller types (e.g., uint16_t, uint8_t)
119:       swapArray(valueBytesVec.data(), type, count);
120:     }
121:     os.write(reinterpret_cast<const char*>(valueBytesVec.data()), 4);
122:   }
123:   else {
124:     // Values do not fit in 4 bytes, write the offset
125:     writeValue(os, valueOffset, mustSwap);
126:     std::streampos offset = static_cast<std::streampos>(valueOffset);
127:     if (mustSwap) {
128:       std::vector<std::byte> swappedValues(values, values+valueBytes);
129:       swapArray(swappedValues.data(), type, count);
130:       writeAt(os, offset, swappedValues.data(), valueBytes);
131:     }
132:     else {
133:       writeAt(os, offset, values, valueBytes);
134:     }
135:   }
136: 
137:   return os;
138: }
