180: TEST_CASE("TiffImage Header class") {
181: 
182:   std::cout << "TiffCraft version: " << TiffCraft::version() << std::endl;
183: 
184:   // Define the expected structure of the TIFF header
185:   // It should be 8 bytes in total:
186:   struct HeaderBytes {
187:       uint16_t byteOrder;       // 0x4949 for "II", 0x4D4D for "MM"
188:       uint16_t magicNumber;     // 42
189:       uint32_t firstIFDOffset;  // Offset of the first IFD
190: 
191:       HeaderBytes(uint16_t bo = 0x4949, uint16_t mn = 42, uint32_t ifdOffset = 8)
192:           : byteOrder(bo), magicNumber(mn), firstIFDOffset(ifdOffset)
193:       {
194:         if (std::endian::native == std::endian::little && bo == 0x4D4D // "MM" big-endian
195:             || std::endian::native == std::endian::big && bo == 0x4949) { // "II" little-endian
196:           magicNumber = std::byteswap(magicNumber);
197:           firstIFDOffset = std::byteswap(firstIFDOffset);
198:         }
199:       }
200: 
201:       std::ostream& write(std::ostream& os) const {
202:         auto startPos = os.tellp();
203:         os.write(reinterpret_cast<const char*>(&byteOrder), sizeof(byteOrder));
204:         os.write(reinterpret_cast<const char*>(&magicNumber), sizeof(magicNumber));
205:         os.write(reinterpret_cast<const char*>(&firstIFDOffset), sizeof(firstIFDOffset));
206:         auto endPos = os.tellp();
207:         if (endPos - startPos != sizeof(HeaderBytes)) {
208:           throw std::runtime_error("HeaderBytes size mismatch");
209:         }
210:         return os;
211:       }
212:   };
213: 
214:   { // Test little-endian header
215:     HeaderBytes headerBytes{ 0x4949, 42, 8 };
216:     std::stringstream stream;
217:     headerBytes.write(stream);
218: 
219:     TiffImage::Header header = TiffImage::Header::read(stream);
220:     CHECK(header.byteOrder() == std::endian::little);
221:     CHECK(header.equalsHostByteOrder() == isHostLittleEndian());
222:   }
223: 
224:   { // Test big-endian header
225:     HeaderBytes headerBytes{ 0x4D4D, 42, 8 };
226:     std::stringstream stream;
227:     headerBytes.write(stream);
228: 
229:     TiffImage::Header header = TiffImage::Header::read(stream);
230:     CHECK(header.byteOrder() == std::endian::big);
231:     CHECK(header.equalsHostByteOrder() == isHostBigEndian());
232:   }
233: 
234:   { // Test wrong byte order
235:     HeaderBytes headerBytes{ 0x4D49, 42, 8 };
236:     std::stringstream stream;
237:     headerBytes.write(stream);
238:     // This should throw an exception due to invalid byte order
239:     CHECK_THROWS_AS(TiffImage::Header::read(stream), std::runtime_error);
240:   }
241: 
242:   { // Test wrong magic number
243:     HeaderBytes headerBytes{ 0x4949, 43, 8 }; // Magic number should be 42
244:     std::stringstream stream;
245:     headerBytes.write(stream);
246:     // This should throw an exception due to invalid magic number
247:     CHECK_THROWS_AS(TiffImage::Header::read(stream), std::runtime_error);
248:   }
