498: TEST_CASE("Malformed TIFF input") {
499: 
500:   { // (a) ASCII entry with count == 0
501:     std::stringstream stream;
502:     writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
503:     writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
504:     writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
505:     // IFD at offset 8
506:     writeValue(stream, static_cast<uint16_t>(1), false);                      // 1 entry
507:     writeValue(stream, static_cast<uint16_t>(Tag::ImageDescription), false);  // Tag
508:     writeValue(stream, static_cast<uint16_t>(Type::ASCII), false);            // Type
509:     writeValue(stream, static_cast<uint32_t>(0), false);                      // Count == 0
510:     writeValue(stream, static_cast<uint32_t>(0), false);                      // Inline value
511:     writeValue(stream, static_cast<uint32_t>(0), false);                      // Next IFD offset
512:     CHECK_THROWS_AS(TiffImage::read(stream), std::runtime_error);
513:   }
514: 
515:   { // (b) Cyclic IFD offset
516:     std::stringstream stream;
517:     writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
518:     writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
519:     writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
520:     // IFD at offset 8: 0 entries, next IFD offset points back to itself
521:     writeValue(stream, static_cast<uint16_t>(0), false);      // 0 entries
522:     writeValue(stream, static_cast<uint32_t>(8), false);      // Next IFD offset (cyclic)
523:     CHECK_THROWS_AS(TiffImage::read(stream), std::runtime_error);
524:   }
525: 
526:   { // (c) Truncated strip: strip data is missing from the stream
527:     std::vector<TiffImage::IFD::Entry> entries;
528:     auto addEntry = [&entries](
529:       uint16_t tag, Type type, uint32_t count,
530:       const std::vector<uint8_t>& values,
531:       uint32_t valueOffset = 0, bool mustSwap = false) {
532:         std::stringstream stream;
533:         // Write the entry
534:         write_IFD_entry(
535:           stream, static_cast<Tag>(tag), type, count,
536:           reinterpret_cast<const std::byte*>(values.data()),
537:           valueOffset, mustSwap);
538:         // Read the entry back
539:         TiffImage::IFD::Entry entry = TiffImage::IFD::Entry::read(stream, mustSwap);
540:         // Add the entry to the vector
541:         entries.push_back(entry);
542:     };
543:     // Entries must be sorted in ascending tag order
544:     addEntry(0x0103, Type::SHORT, 1, { 1 });                  // Compression = none
545:     addEntry(0x0106, Type::SHORT, 1, { 0 });                  // PhotometricInterpretation = WhiteIsZero
546:     addEntry(0x0111, Type::LONG, 1, { 100, 0, 0, 0 });        // StripOffsets = 100 (beyond end of stream)
547:     addEntry(0x0117, Type::LONG, 1, { 232, 3, 0, 0 });        // StripByteCounts = 1000
548: 
549:     std::stringstream stream;
550:     writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
551:     writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
552:     writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
553:     // IFD at offset 8 (only the IFD; the strip data is not written)
554:     write_IFD(stream, entries, false);
555:     writeValue(stream, static_cast<uint32_t>(0), false);      // Next IFD offset
556:     CHECK_THROWS_AS(
557:       load(stream, [](auto&&...) { }, LoadParams{}),
558:       std::runtime_error);
559:   }
560: 
561:   { // (d) RATIONAL entry with a zero denominator
562:     std::stringstream stream;
563:     writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
564:     writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
565:     writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
566:     // IFD at offset 8
567:     writeValue(stream, static_cast<uint16_t>(1), false);                 // 1 entry
568:     writeValue(stream, static_cast<uint16_t>(Tag::XResolution), false);  // Tag
569:     writeValue(stream, static_cast<uint16_t>(Type::RATIONAL), false);    // Type
570:     writeValue(stream, static_cast<uint32_t>(1), false);                 // Count
571:     writeValue(stream, static_cast<uint32_t>(26), false);                // Value offset (after the IFD table)
572:     writeValue(stream, static_cast<uint32_t>(0), false);                 // Next IFD offset (offset 22)
573:     // RATIONAL value at offset 26: numerator = 300, denominator = 0
574:     writeValue(stream, static_cast<uint32_t>(300), false);               // Numerator
575:     writeValue(stream, static_cast<uint32_t>(0), false);                 // Denominator
576:     // Entry::read does not divide rationals, so reading the image must not throw
577:     TiffImage image = TiffImage::read(stream);
578:     REQUIRE(image.ifds().size() == 1);
579:     CHECK_THROWS_AS(TiffExporter::getIntVec(image.ifds()[0], Tag::XResolution), std::runtime_error);
580:   }
581: }
